#!/usr/bin/env node

/**
 * ═══════════════════════════════════════════════════════════════
 *  EduPortal Phase 4 — Upload Pipeline Stress Test
 * ═══════════════════════════════════════════════════════════════
 *
 * Usage:
 *   node scripts/stress-test-upload.js --cookie "<cookie-string>" [--base-url https://www.edu-platform.me] [--files 150]
 *
 * This script mocks the exact JSON payloads generated by the frontend
 * and fires them at the /sync-hierarchy and /upload-complete-batch
 * endpoints to measure database throughput under bulk load.
 *
 * ── HOW TO GET YOUR SESSION COOKIE ──────────────────────────────
 *
 *   1. Open your EduPortal site in Chrome/Edge.
 *   2. Log in as an admin.
 *   3. Open DevTools → Application tab → Cookies → your domain.
 *   4. Find the cookie named: next-auth.session-token
 *      (On Vercel production it may be: __Secure-next-auth.session-token)
 *   5. Copy the FULL value (the long JWT/opaque string).
 *   6. Pass it to this script using ONE of these methods:
 *
 *      Method A (--cookie flag):
 *        node scripts/stress-test-upload.js --cookie "next-auth.session-token=abc123def..."
 *
 *      Method B (env var):
 *        ADMIN_COOKIE="next-auth.session-token=abc123def..." node scripts/stress-test-upload.js
 *
 *      Method C (for Vercel production with __Secure- prefix):
 *        node scripts/stress-test-upload.js --cookie "__Secure-next-auth.session-token=abc123def..."
 *
 *   7. Use --dry-run to test payload generation without sending requests.
 *
 * ────────────────────────────────────────────────────────────────
 *
 * Examples:
 *   node scripts/stress-test-upload.js --cookie "next-auth.session-token=abc" --files 200
 *   node scripts/stress-test-upload.js --cookie "next-auth.session-token=abc" --base-url https://www.edu-platform.me --files 500
 *   node scripts/stress-test-upload.js --dry-run --files 1000
 */

const http = require('http');
const https = require('https');
const { URL } = require('url');

// ── CLI Argument Parsing ──
const args = process.argv.slice(2);
function getArg(name, defaultValue) {
  const idx = args.indexOf(`--${name}`);
  return idx !== -1 && args[idx + 1] ? args[idx + 1] : defaultValue;
}

const BASE_URL = getArg('base-url', 'http://localhost:3000');
const TOTAL_FILES = parseInt(getArg('files', '150'), 10);
const NUM_SUBJECTS = parseInt(getArg('subjects', '5'), 10);
const LESSONS_PER_SUBJECT = parseInt(getArg('lessons', '4'), 10);
// Support both --cookie CLI arg and ADMIN_COOKIE env var
const ADMIN_COOKIE = getArg('cookie', '') || process.env.ADMIN_COOKIE || '';
const DRY_RUN = args.includes('--dry-run');

// ── Display config ──
console.log('');
console.log('╔══════════════════════════════════════════════════════════════╗');
console.log('║       EduPortal Upload Pipeline Stress Test — Phase 4       ║');
console.log('╠══════════════════════════════════════════════════════════════╣');
console.log(`║  Base URL:      ${BASE_URL.padEnd(43)}║`);
console.log(`║  Total Files:   ${String(TOTAL_FILES).padEnd(43)}║`);
console.log(`║  Subjects:      ${String(NUM_SUBJECTS).padEnd(43)}║`);
console.log(`║  Lessons/Subj:  ${String(LESSONS_PER_SUBJECT).padEnd(43)}║`);
console.log(`║  Dry Run:       ${String(DRY_RUN).padEnd(43)}║`);
console.log(`║  Cookie Set:    ${String(!!ADMIN_COOKIE).padEnd(43)}║`);
console.log(`║  Cookie Name:   ${(ADMIN_COOKIE.split('=')[0] || 'NONE').padEnd(43)}║`);
console.log('╚══════════════════════════════════════════════════════════════╝');
console.log('');

if (!ADMIN_COOKIE && !DRY_RUN) {
  console.error('❌ ERROR: No session cookie provided.');
  console.error('');
  console.error('   Pass your admin session cookie using one of:');
  console.error('     --cookie "next-auth.session-token=YOUR_TOKEN_HERE"');
  console.error('     ADMIN_COOKIE="next-auth.session-token=YOUR_TOKEN_HERE"');
  console.error('');
  console.error('   To find your cookie:');
  console.error('     1. Log into EduPortal as admin in Chrome');
  console.error('     2. DevTools → Application → Cookies → your domain');
  console.error('     3. Copy the value of "next-auth.session-token"');
  console.error('        (on Vercel: "__Secure-next-auth.session-token")');
  console.error('');
  console.error('   Or use --dry-run to generate payloads without sending.');
  process.exit(1);
}

// ── Mock Data Generators ──

const FILE_TYPES = [
  { ext: '.pdf',  mime: 'application/pdf', type: 'pdf' },
  { ext: '.pptx', mime: 'application/vnd.openxmlformats-officedocument.presentationml.presentation', type: 'powerpoint' },
  { ext: '.docx', mime: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document', type: 'powerpoint' },
  { ext: '.png',  mime: 'image/png', type: 'image' },
  { ext: '.jpg',  mime: 'image/jpeg', type: 'image' },
  { ext: '.mp4',  mime: 'video/mp4', type: 'video' },
];

const SUBJECT_NAMES = [
  'Advanced Mathematics', 'Quantum Physics', 'Organic Chemistry',
  'Data Structures', 'Linear Algebra', 'Thermodynamics',
  'Digital Logic', 'Electromagnetics', 'Probability Theory',
  'Machine Learning'
];

const LESSON_PREFIXES = [
  'Introduction to', 'Fundamentals of', 'Advanced Topics in',
  'Lab Session', 'Tutorial', 'Problem Set',
  'Midterm Review', 'Case Study', 'Workshop',
  'Practical', 'Lecture Notes', 'Summary',
  'Drill Exercises', 'Project Guidelines', 'Formula Sheet',
  'Past Paper Analysis', 'Revision', 'Final Review',
  'Supplementary Material', 'Extension Work'
];

function slugify(str) {
  return str.toLowerCase().replace(/[^a-z0-9]/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '');
}

function generateSubjects(count) {
  const subjects = [];
  for (let i = 0; i < count; i++) {
    const name = SUBJECT_NAMES[i % SUBJECT_NAMES.length] + (i >= SUBJECT_NAMES.length ? ` ${Math.floor(i / SUBJECT_NAMES.length) + 1}` : '');
    subjects.push({
      name,
      slug: slugify(name),
      id: `mock-subject-${i}`
    });
  }
  return subjects;
}

function generateLessons(subjects, lessonsPerSubject) {
  const lessons = [];
  for (const subject of subjects) {
    for (let i = 0; i < lessonsPerSubject; i++) {
      const name = `${LESSON_PREFIXES[i % LESSON_PREFIXES.length]} ${subject.name.split(' ').pop()}`;
      lessons.push({
        subjectName: subject.name,
        subjectSlug: subject.slug,
        lessonName: name,
        lessonSlug: slugify(name),
        subjectId: subject.id,
        lessonId: `mock-lesson-${subject.slug}-${i}`
      });
    }
  }
  return lessons;
}

function generateIdempotencyKey(fileName, idx) {
  const raw = `${fileName}|${1024 * (idx + 1)}|${Date.now() - idx * 100}|${fileName}`;
  let hash = 0;
  for (let i = 0; i < raw.length; i++) {
    hash = ((hash << 5) - hash) + raw.charCodeAt(i);
    hash |= 0;
  }
  return `ik_${Math.abs(hash).toString(36)}_${Date.now().toString(36)}_${idx}`;
}

function generateMockFiles(totalFiles, lessons) {
  const files = [];
  for (let i = 0; i < totalFiles; i++) {
    const lesson = lessons[i % lessons.length];
    const fileSpec = FILE_TYPES[i % FILE_TYPES.length];
    const fileNum = Math.floor(i / lessons.length) + 1;
    const fileName = `lecture_${fileNum}_material_${i}${fileSpec.ext}`;
    
    files.push({
      lessonId: lesson.lessonId,
      parentId: null,
      fileName: fileName,
      fileType: fileSpec.type,
      contentType: fileSpec.mime,
      publicUrl: `https://mock-cdn.r2.dev/${lesson.subjectSlug}/${lesson.lessonSlug}/${Date.now()}_${fileName}`,
      itemType: 'file',
      vimeoId: '',
      idempotencyKey: generateIdempotencyKey(fileName, i)
    });
  }
  return files;
}

// ── HTTP Client ──

/**
 * Logs a non-200 HTTP response with full diagnostic info.
 * This is the core fix for blind error swallowing.
 */
function logHttpError(label, result) {
  console.error(`  → ❌ ${label}: HTTP ${result.status}`);
  const bodyStr = typeof result.body === 'string'
    ? result.body
    : JSON.stringify(result.body, null, 2);
  // Print up to 500 chars of the response body for diagnosis
  console.error(`  → Response body: ${bodyStr.slice(0, 500)}`);
  // Surface redirect location if middleware is bouncing us
  if (result.headers?.location) {
    console.error(`  → Redirect Location: ${result.headers.location}`);
  }
  // Surface set-cookie headers that hint at session issues  
  if (result.headers?.['set-cookie']) {
    console.error(`  → Set-Cookie header present (session may be invalid)`);
  }
}

function makeRequest(path, body) {
  return new Promise((resolve, reject) => {
    const url = new URL(path, BASE_URL);
    const isHttps = url.protocol === 'https:';
    const lib = isHttps ? https : http;

    const payload = JSON.stringify(body);
    const options = {
      hostname: url.hostname,
      port: url.port || (isHttps ? 443 : 80),
      path: url.pathname,
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
        'Cookie': ADMIN_COOKIE,
      },
      timeout: 120000, // 2 minute timeout for massive batches
    };

    const req = lib.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        let parsedBody;
        try {
          parsedBody = JSON.parse(data);
        } catch {
          parsedBody = data;
        }
        // Always resolve — we handle HTTP errors in the test logic, not here
        resolve({
          status: res.statusCode,
          headers: res.headers,
          body: parsedBody,
          ok: res.statusCode >= 200 && res.statusCode < 300,
          rawBody: data,
        });
      });
    });

    req.on('error', (err) => {
      reject(new Error(`${err.code || 'NETWORK_ERROR'}: ${err.message} (is ${BASE_URL} running?)`));
    });
    req.on('timeout', () => {
      req.destroy();
      reject(new Error(`TIMEOUT: Request to ${path} timed out after 120s`));
    });
    req.write(payload);
    req.end();
  });
}

// ── Test Execution ──

async function runStressTest() {
  const subjects = generateSubjects(NUM_SUBJECTS);
  const lessons = generateLessons(subjects, LESSONS_PER_SUBJECT);
  const mockFiles = generateMockFiles(TOTAL_FILES, lessons);

  console.log(`📊 Generated ${subjects.length} subjects, ${lessons.length} lessons, ${mockFiles.length} file metadata objects`);
  console.log(`📦 Batch payload size: ${(Buffer.byteLength(JSON.stringify({ items: mockFiles })) / 1024).toFixed(1)} KB`);
  console.log('');

  // ────────────────────────────────────────────
  //  TEST 1: Sync Hierarchy Stress
  // ────────────────────────────────────────────
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('  TEST 1: /api/admin/sync-hierarchy');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

  const syncPayload = {
    items: lessons.map(l => ({
      subjectName: l.subjectName,
      lessonName: l.lessonName
    }))
  };

  console.log(`  → Sending ${syncPayload.items.length} subject/lesson pairs`);
  console.log(`  → Payload size: ${(Buffer.byteLength(JSON.stringify(syncPayload)) / 1024).toFixed(1)} KB`);

  if (!DRY_RUN) {
    console.time('  ⏱  sync-hierarchy response time');
    try {
      const syncResult = await makeRequest('/api/admin/sync-hierarchy', syncPayload);
      console.timeEnd('  ⏱  sync-hierarchy response time');
      console.log(`  → Status: ${syncResult.status}`);
      
      if (!syncResult.ok) {
        logHttpError('sync-hierarchy', syncResult);
      } else if (syncResult.body.mappings) {
        const mappings = syncResult.body.mappings;
        const resolvedCount = Object.keys(mappings).length;
        console.log(`  → Resolved: ${resolvedCount}/${syncPayload.items.length} pairs`);
        
        // Update mock file lessonIds with real IDs from sync
        for (const file of mockFiles) {
          const lesson = lessons.find(l => l.lessonId === file.lessonId);
          if (lesson) {
            const mapping = mappings[`${lesson.subjectName}|${lesson.lessonName}`];
            if (mapping) {
              file.lessonId = mapping.lessonId;
            }
          }
        }
        console.log('  → ✅ Mock file IDs updated with real Supabase IDs');
      } else {
        console.log(`  → ⚠️  Unexpected 2xx body:`, JSON.stringify(syncResult.body).slice(0, 300));
      }
    } catch (err) {
      console.timeEnd('  ⏱  sync-hierarchy response time');
      console.error(`  → ❌ CONNECTION FAILED:`, err.message);
    }
  } else {
    console.log('  → [DRY RUN] Payload generated, not sent.');
    console.log(`  → Sample: ${JSON.stringify(syncPayload.items.slice(0, 2))}`);
  }

  console.log('');

  // ────────────────────────────────────────────
  //  TEST 2: Batch Upload Complete Stress
  // ────────────────────────────────────────────
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('  TEST 2: /api/admin/upload-complete-batch');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

  const batchPayload = { items: mockFiles };
  const payloadSizeKB = (Buffer.byteLength(JSON.stringify(batchPayload)) / 1024).toFixed(1);

  console.log(`  → Sending ${mockFiles.length} file metadata objects`);
  console.log(`  → Payload size: ${payloadSizeKB} KB`);
  console.log(`  → Vercel 4.5MB limit usage: ${((Buffer.byteLength(JSON.stringify(batchPayload)) / (4.5 * 1024 * 1024)) * 100).toFixed(1)}%`);

  if (!DRY_RUN) {
    console.time('  ⏱  upload-complete-batch response time');
    try {
      const batchResult = await makeRequest('/api/admin/upload-complete-batch', batchPayload);
      console.timeEnd('  ⏱  upload-complete-batch response time');
      console.log(`  → Status: ${batchResult.status}`);
      
      if (!batchResult.ok) {
        logHttpError('upload-complete-batch', batchResult);
      } else if (batchResult.body && typeof batchResult.body === 'object') {
        console.log(`  → Created:    ${batchResult.body.created ?? 'N/A'}`);
        console.log(`  → Idempotent: ${batchResult.body.idempotent ?? 'N/A'}`);
        console.log(`  → Missing R2: ${batchResult.body.missingR2 ?? 'N/A'}`);
        console.log(`  → Duplicates: ${batchResult.body.duplicates ?? 'N/A'}`);
        
        if (batchResult.body.error) {
          console.log(`  → ⚠️  Error: ${batchResult.body.error}`);
        }
      } else {
        console.log(`  → Raw response: ${String(batchResult.body).slice(0, 300)}`);
      }
    } catch (err) {
      console.timeEnd('  ⏱  upload-complete-batch response time');
      console.error(`  → ❌ CONNECTION FAILED:`, err.message);
    }
  } else {
    console.log('  → [DRY RUN] Payload generated, not sent.');
    console.log(`  → Sample item: ${JSON.stringify(mockFiles[0])}`);
  }

  console.log('');

  // ────────────────────────────────────────────
  //  TEST 3: Concurrent Batch Stress
  //  Fires multiple smaller batches simultaneously
  // ────────────────────────────────────────────
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('  TEST 3: Concurrent batch requests (simulating race)');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

  const CONCURRENT_BATCHES = 3;
  const ITEMS_PER_BATCH = Math.ceil(TOTAL_FILES / CONCURRENT_BATCHES);

  console.log(`  → Splitting ${TOTAL_FILES} files into ${CONCURRENT_BATCHES} concurrent batches of ~${ITEMS_PER_BATCH}`);

  if (!DRY_RUN) {
    // Generate fresh files with unique idempotency keys to avoid collision with test 2
    const freshFiles = generateMockFiles(TOTAL_FILES, lessons);
    
    const batches = [];
    for (let i = 0; i < CONCURRENT_BATCHES; i++) {
      const start = i * ITEMS_PER_BATCH;
      const end = Math.min(start + ITEMS_PER_BATCH, TOTAL_FILES);
      batches.push(freshFiles.slice(start, end));
    }

    console.time('  ⏱  concurrent batch total time');
    const concurrentResults = await Promise.allSettled(
      batches.map((batch, idx) => {
        const label = `Batch ${idx + 1}`;
        console.log(`  → ${label}: sending ${batch.length} items...`);
        console.time(`  ⏱  ${label}`);
        return makeRequest('/api/admin/upload-complete-batch', { items: batch })
          .then(r => {
            console.timeEnd(`  ⏱  ${label}`);
            return { idx, ...r };
          });
      })
    );
    console.timeEnd('  ⏱  concurrent batch total time');

    for (const result of concurrentResults) {
      if (result.status === 'fulfilled') {
        const r = result.value;
        if (!r.ok) {
          logHttpError(`Batch ${r.idx + 1}`, r);
        } else {
          console.log(`  → Batch ${r.idx + 1}: HTTP ${r.status} — created: ${r.body?.created ?? 'N/A'}, missingR2: ${r.body?.missingR2 ?? 'N/A'}`);
        }
      } else {
        console.error(`  → Batch CONNECTION FAILED:`, result.reason?.message);
      }
    }
  } else {
    console.log('  → [DRY RUN] Would send 3 concurrent requests.');
  }

  console.log('');

  // ────────────────────────────────────────────
  //  TEST 4: Payload Size Boundary Test
  // ────────────────────────────────────────────
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
  console.log('  TEST 4: Payload size boundary analysis');
  console.log('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');

  const testSizes = [50, 100, 250, 500, 1000, 2000, 5000];
  for (const size of testSizes) {
    const testFiles = generateMockFiles(size, lessons);
    const payloadBytes = Buffer.byteLength(JSON.stringify({ items: testFiles }));
    const pct = ((payloadBytes / (4.5 * 1024 * 1024)) * 100).toFixed(1);
    const status = payloadBytes > 4.5 * 1024 * 1024 ? '❌ EXCEEDS' : '✅ SAFE';
    console.log(`  ${String(size).padStart(5)} files → ${(payloadBytes / 1024).toFixed(0).padStart(6)} KB → ${pct.padStart(5)}% of 4.5MB limit → ${status}`);
  }

  console.log('');

  // ────────────────────────────────────────────
  //  Summary
  // ────────────────────────────────────────────
  console.log('╔══════════════════════════════════════════════════════════════╗');
  console.log('║                    Stress Test Complete                     ║');
  console.log('╚══════════════════════════════════════════════════════════════╝');
  console.log('');
  console.log('Post-test cleanup:');
  console.log('  • Run purge-orphans (dry-run first) to check for ghost files:');
  console.log(`    curl -X POST ${BASE_URL}/api/admin/purge-orphans -H "Cookie: ${ADMIN_COOKIE ? '...' : 'ADMIN_COOKIE'}" -H "Content-Type: application/json" -d '{"purge": false}'`);
  console.log('');
}

runStressTest().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
